update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Shaviyani Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 800 residents"},{"label":"Size","value":"1.0 km long, 0.6 km wide"},{"label":"Distance from Male","value":"218 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Serene culture, tranquil beaches, relaxing traditions"},{"label":"Best For","value":"Culture enthusiasts, beach lovers, peace seekers, nature lovers"}],"island_overview":["Maroshi Island is a serene local island in Shaviyani Atoll that offers visitors a peaceful glimpse into traditional Maldivian life in the northern region of the archipelago. This tranquil island combines natural beauty with a relaxing atmosphere, providing an ideal destination for travelers seeking calming cultural experiences and serene tropical surroundings.","Known for its tranquil beaches, serene coral reefs, and relaxing marine biodiversity, Maroshi provides peaceful opportunities for snorkeling, swimming, and underwater exploration. The island''s peaceful community embraces visitors with traditional Maldivian warmth and shares their relaxing way of life with serene hospitality.","What makes Maroshi special is its serene natural environment and peaceful northern location. Visitors can enjoy tranquil beaches, explore rich marine ecosystems, and experience relaxing island culture while staying in comfortable accommodations that showcase the serene Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Maroshi Island is serenely located in the northern part of Shaviyani Atoll, approximately 218 kilometers from Male. This location provides a serene and peaceful experience in the northern Maldives, while maintaining relaxing accessibility through seap